import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Как устроен Rimlink","description":"","frontmatter":{"pageId":"overview","contentRevision":1},"headers":[],"relativePath":"ru/overview.md","filePath":"ru/overview.md"}'),l={name:"ru/overview.md"};function o(n,e,s,d,h,c){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="как-устроен-rimlink" tabindex="-1">Как устроен Rimlink <a class="header-anchor" href="#как-устроен-rimlink" aria-label="Permalink to &quot;Как устроен Rimlink&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Сервер хранит общий мир, сведения о поселениях, сейвы и сделки. Игрок развивает собственную колонию в своём темпе; чужое поселение видно на планете с индикатором присутствия. Сохранение передаётся серверу и возвращается при следующем входе.</p><p>Общение, подарки, рынок, аукционы и заказы соединяют колонии без общей симуляции. Визиты и асинхронные рейды используют копию карты. Live-режим передаёт гостю живое состояние хозяина; постоянная совместная колония дополнительно сохраняет разрешения на конкретных пешек.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Офлайн-колония не симулируется постоянно. Live не делает гостя владельцем сейва. Союз и слой влияния не дают права управлять чужой колонией.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./players/live">Live: живая карта</a></li><li><a href="./players/coop">Постоянная совместная колония</a></li><li><a href="./players/economy">Кошелёк, почта и рынок</a></li></ul>',9)])])}const u=a(l,[["render",o]]);export{p as __pageData,u as default};
